entries[471368] = { ["name"] = "Blair's \"Gold\" Fish Exchange", ["text"] = "5 yd range\n3.2 sec cast\nLocated along the central channel of The Vatworks, Blair Bass and her team of Anglers have taken a special interest to the local \"Gold\" Fish inhabiting the Undermine.\n\nStop by to take part in the preservation effort and earn rewards!\nProfession:\nFishing (225)" }
